{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/compare-mark.json
    One cell value of ComparisonTable: yes shows a check, no a dash (both with the hidden word for screen readers), any other value is shown as text.
    Props (p): value, yes, no. *}
{var $v_value = ($p['value'] ?? null)}
{var $v_yes = ($p['yes'] ?? null)}
{var $v_no = ($p['no'] ?? null)}
{if og_t(og_eq($v_value, 'yes'))}
  {capture $c_2}
    {=og_include('icons/LucideIcon.latte', ['name' => 'check', 'size' => 16, 'class' => 'text-foreground'])|noescape}
    {capture $c_1}
      {=og_text($v_yes)}
    {/capture}
    {=og_include('compose/Inline.latte', ['class' => 'sr-only', 'children' => (string) $c_1])|noescape}
  {/capture}
  {=og_include('compose/Inline.latte', ['class' => 'inline-flex items-center gap-2', 'attrs' => og_attrs(['data-mark', 'yes', 'data-slot', 'compare-mark']), 'children' => (string) $c_2])|noescape}
{/if}
{if og_t(og_eq($v_value, 'no'))}
  {capture $c_4}
    {=og_include('icons/LucideIcon.latte', ['name' => 'minus', 'size' => 16])|noescape}
    {capture $c_3}
      {=og_text($v_no)}
    {/capture}
    {=og_include('compose/Inline.latte', ['class' => 'sr-only', 'children' => (string) $c_3])|noescape}
  {/capture}
  {=og_include('compose/Inline.latte', ['class' => 'inline-flex items-center gap-2 text-muted-foreground', 'attrs' => og_attrs(['data-mark', 'no', 'data-slot', 'compare-mark']), 'children' => (string) $c_4])|noescape}
{/if}
{if og_t(og_and([!(og_eq($v_value, 'yes')), !(og_eq($v_value, 'no'))]))}
  {capture $c_5}
    {=og_text($v_value)}
  {/capture}
  {=og_include('compose/Inline.latte', ['attrs' => og_attrs(['data-slot', 'compare-mark']), 'children' => (string) $c_5])|noescape}
{/if}
